"""Trial-local, allowlisted sudo emulation for rootless Apptainer runs."""

from __future__ import annotations

import json
import os
import secrets
import socket
import stat
import threading
from datetime import datetime, timezone
from pathlib import Path
from typing import BinaryIO

from .inject import InjectionError


# Generate a small client that accepts only the sudo forms used by this experiment.
def _sudo_client_source(*, host: str, port: int, token: str) -> str:
    return f'''#!/usr/bin/python3
# Generated by HealthAgentBench faults; do not edit.

import json
import pathlib
import socket
import sys
import tempfile

BROKER_HOST = {host!r}
BROKER_PORT = {port}
BROKER_TOKEN = {token!r}


def fail(message, code=1):
    print(f"sudo: {{message}}", file=sys.stderr)
    raise SystemExit(code)


def request(payload):
    payload["token"] = BROKER_TOKEN
    connection = socket.create_connection((BROKER_HOST, BROKER_PORT), timeout=10)
    stream = connection.makefile("rwb", buffering=0)
    stream.write(json.dumps(payload, sort_keys=True).encode("utf-8") + b"\\n")
    header_line = stream.readline()
    if not header_line:
        fail("privilege broker returned no response")
    header = json.loads(header_line)
    if not header.get("ok"):
        fail(str(header.get("error", "request denied")))
    return connection, stream, header


arguments = sys.argv[1:]
non_interactive = False
while arguments and arguments[0] in {{"-n", "--non-interactive"}}:
    non_interactive = True
    arguments.pop(0)
if arguments == ["-l"] or arguments == ["--list"]:
    _, stream, header = request({{"operation": "list"}})
    print(header["message"])
    raise SystemExit(0)
if not arguments:
    fail("a command is required")
command_name = pathlib.Path(arguments[0]).name
if command_name == "cat" and len(arguments) == 2:
    _, stream, header = request({{"operation": "cat", "target": arguments[1]}})
    remaining = int(header["size"])
    while remaining:
        chunk = stream.read(min(1024 * 1024, remaining))
        if not chunk:
            fail("privilege broker truncated the protected file")
        sys.stdout.buffer.write(chunk)
        remaining -= len(chunk)
    raise SystemExit(0)
if command_name == "cp" and len(arguments) == 3:
    _, stream, header = request({{"operation": "cp", "target": arguments[1]}})
    destination = pathlib.Path(arguments[2])
    resolved_destination = destination.resolve()
    workspace_root = pathlib.Path("/workspace")
    if (
        resolved_destination != workspace_root
        and workspace_root not in resolved_destination.parents
    ):
        fail("copy destination is outside /workspace")
    remaining = int(header["size"])
    with destination.open("wb") as output:
        while remaining:
            chunk = stream.read(min(1024 * 1024, remaining))
            if not chunk:
                fail("privilege broker truncated the protected file")
            output.write(chunk)
            remaining -= len(chunk)
    raise SystemExit(0)
if command_name == "chmod" and len(arguments) == 3:
    _, stream, header = request(
        {{"operation": "chmod", "mode": arguments[1], "target": arguments[2]}}
    )
    if header.get("restore"):
        destination = pathlib.Path(arguments[2])
        remaining = int(header["size"])
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=".healthagent-restore-",
            dir=str(destination.parent),
        )
        temporary = pathlib.Path(temporary_name)
        try:
            with open(descriptor, "wb", closefd=True) as output:
                while remaining:
                    chunk = stream.read(min(1024 * 1024, remaining))
                    if not chunk:
                        fail("privilege broker truncated the protected file")
                    output.write(chunk)
                    remaining -= len(chunk)
            temporary.chmod(int(header["mode"], 8))
            temporary.replace(destination)
        finally:
            if temporary.exists():
                temporary.unlink()
    raise SystemExit(0)
suffix = " in non-interactive mode" if non_interactive else ""
fail(f"command is outside the experiment allowlist{{suffix}}")
'''


# Create the Agent-visible sudo client without installing anything into the SIF.
def write_privilege_runtime(
    directory: Path,
    *,
    host: str,
    port: int,
    token: str,
) -> Path:
    runtime = directory / "privilege-runtime"
    bin_directory = runtime / "bin"
    bin_directory.mkdir(parents=True, exist_ok=False)
    wrapper = bin_directory / "sudo"
    wrapper.write_text(
        _sudo_client_source(host=host, port=port, token=token),
        encoding="utf-8",
    )
    wrapper.chmod(0o755)
    return runtime


class PrivilegeBroker:
    """Serve one protected file through an exact-path, audited capability."""

    def __init__(
        self,
        *,
        source: BinaryIO,
        target: Path | None,
        container_target: str,
        audit_path: Path,
        condition: str,
        readable_mode: int,
    ) -> None:
        self.source = source
        self.target = target
        self.container_target = container_target
        self.audit_path = audit_path
        self.condition = condition
        self.readable_mode = readable_mode | stat.S_IRUSR
        self.host = "127.0.0.1"
        self.port = 0
        self.token = secrets.token_urlsafe(32)
        self._socket: socket.socket | None = None
        self._thread: threading.Thread | None = None
        self._stopping = threading.Event()

    # Start listening before the Agent server so recovery is available immediately.
    def start(self) -> None:
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.bind((self.host, 0))
        listener.listen(8)
        listener.settimeout(0.2)
        self.port = int(listener.getsockname()[1])
        self._socket = listener
        self._thread = threading.Thread(
            target=self._serve,
            name="healthagent-privilege-broker",
            daemon=True,
        )
        self._thread.start()

    # Stop accepting requests and close the pristine source descriptor.
    def stop(self) -> None:
        self._stopping.set()
        if self._socket is not None:
            self._socket.close()
        if self._thread is not None:
            self._thread.join(timeout=5)
        self.source.close()

    # Accept serial requests; one Agent does not require an unbounded worker pool.
    def _serve(self) -> None:
        assert self._socket is not None
        while not self._stopping.is_set():
            try:
                connection, _ = self._socket.accept()
            except TimeoutError:
                continue
            except OSError:
                break
            with connection:
                self._handle(connection)

    # Read a bounded JSON request to avoid turning the broker into a generic service.
    def _read_request(self, connection: socket.socket) -> dict[str, object]:
        received = bytearray()
        while b"\n" not in received and len(received) <= 65536:
            chunk = connection.recv(4096)
            if not chunk:
                break
            received.extend(chunk)
        if b"\n" not in received or len(received) > 65536:
            raise InjectionError("Privilege request is missing or too large")
        value = json.loads(received.split(b"\n", 1)[0])
        if not isinstance(value, dict):
            raise InjectionError("Privilege request must be a JSON object")
        return value

    # Record every allowed and denied operation outside the Agent-visible workspace.
    def _record(self, *, operation: str, allowed: bool, detail: str) -> None:
        event = {
            "event": "protected_file_sudo",
            "condition": self.condition,
            "operation": operation,
            "target": self.container_target,
            "allowed": allowed,
            "detail": detail,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }
        self.audit_path.parent.mkdir(parents=True, exist_ok=True)
        with self.audit_path.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(event, sort_keys=True) + "\n")

    # Send one JSON header before any protected bytes.
    @staticmethod
    def _respond(connection: socket.socket, value: dict[str, object]) -> None:
        connection.sendall(json.dumps(value, sort_keys=True).encode("utf-8") + b"\n")

    # Stream through positional reads so concurrent requests cannot share offsets.
    def _stream_source(
        self,
        connection: socket.socket,
        *,
        header: dict[str, object] | None = None,
    ) -> None:
        size = os.fstat(self.source.fileno()).st_size
        self._respond(connection, {"ok": True, "size": size, **(header or {})})
        offset = 0
        while offset < size:
            chunk = os.pread(self.source.fileno(), min(1024 * 1024, size - offset), offset)
            if not chunk:
                raise InjectionError("Protected source ended before its recorded size")
            connection.sendall(chunk)
            offset += len(chunk)

    # Enforce exact target and operation allowlists for every sudo request.
    def _handle(self, connection: socket.socket) -> None:
        operation = "invalid"
        try:
            request = self._read_request(connection)
            operation = str(request.get("operation", ""))
            if not secrets.compare_digest(str(request.get("token", "")), self.token):
                raise InjectionError("invalid privilege capability token")
            if operation == "list":
                message = (
                    f"(healthagent) NOPASSWD: /bin/cat {self.container_target}, "
                    f"/bin/cp {self.container_target} <workspace-path>, "
                    f"/bin/chmod u+r {self.container_target}"
                )
                self._record(operation=operation, allowed=True, detail="allowlist listed")
                self._respond(connection, {"ok": True, "message": message})
                return
            if request.get("target") != self.container_target:
                raise InjectionError("target is outside the experiment allowlist")
            if operation in {"cat", "cp"}:
                self._record(operation=operation, allowed=True, detail="exact bytes returned")
                self._stream_source(connection)
                return
            if operation == "chmod":
                mode = str(request.get("mode", ""))
                if mode not in {"u+r", "400", "0400", "600", "0600", "644", "0644"}:
                    raise InjectionError("chmod mode is outside the experiment allowlist")
                if self.target is not None:
                    self.target.chmod(self.readable_mode)
                    self._record(
                        operation=operation,
                        allowed=True,
                        detail=f"mode {mode} applied",
                    )
                    self._respond(connection, {"ok": True})
                else:
                    self._record(
                        operation=operation,
                        allowed=True,
                        detail=f"exact bytes restored with mode {mode}",
                    )
                    self._stream_source(
                        connection,
                        header={
                            "restore": True,
                            "mode": f"{self.readable_mode:04o}",
                        },
                    )
                return
            raise InjectionError("command is outside the experiment allowlist")
        except (InjectionError, json.JSONDecodeError, OSError) as error:
            self._record(operation=operation, allowed=False, detail=str(error))
            try:
                self._respond(connection, {"ok": False, "error": str(error)})
            except OSError:
                pass
